package controller;
import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import service.UserService;import model.User;
@WebServlet("/login") public class LoginServlet extends HttpServlet {private final UserService service=new UserService();protected void doPost(HttpServletRequest q,HttpServletResponse p)throws IOException{String n=q.getParameter("username"),pw=q.getParameter("password");if(!service.authenticateUser(n,pw)){p.sendRedirect(q.getContextPath()+"/login.html?error=invalid");return;}User u=service.findByUsername(n.trim()).orElseThrow();HttpSession old=q.getSession(false);if(old!=null)old.invalidate();HttpSession s=q.getSession(true);s.setAttribute("userId",u.getId());s.setAttribute("username",u.getUsername());s.setAttribute("role",u.getRole());s.setMaxInactiveInterval(1800);q.changeSessionId();p.sendRedirect(q.getContextPath()+"/dashboard.jsp");}}